// Finite State Machine
module TopModule (
    input  clk,
    input  x,
    output z
);
    reg q0;
    reg q1;
    reg q2;
    wire [2:0] g0, g1, g2;
    wire [2:0] o;
    wire [2:0] n;
    reg [1:0] state;
    always @(posedge clk) begin
        case (state)
            2'b00: begin
                q0 <= 1'b0;
                q1 <= 1'b0;
                q2 <= 1'b0;
                state <= 2'b01;
            end
            2'b01: begin
                q0 <= x;
                q1 <= ~x;
                q2 <= 1'b1;
                state <= 2'b10;
            end
            2'b10: begin
                q0 <= ~x;
                q1 <= x & ~q1;
                q2 <= x | ~q2;
                state <= 2'b11;
            end
            2'b11: begin
                q0 <= x ^ q0;
                q1 <= x & ~q1;
                q2 <= x | ~q2;
                state <= 2'b00;
            end
        endcase
    end
    assign g0 = {1'b1, q0, 1'b1};
    assign g1 = {1'b1, q1, 1'b1};
    assign g2 = {1'b1, q2, 1'b1};
    assign o = {1'b1, g0, g1, g2};
    assign n = ~o;
    assign z = n[0];
endmodule

